# Secondary Assessment (NREMT EMR test plan, 2025: 4% to 8%). Job tasks: investigate the
# patient's condition through a focused physical exam, interview and past history; reassess to
# find changes. Stroke screening and last known well follow the NASEMSO National Model EMS
# Clinical Guidelines v3.0 (Suspected Stroke/Transient Ischemic Attack). Blood glucose
# monitoring and oral glucose are EMT and above in the national scope model.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "SAMPLE history", "In a SAMPLE history, what does the L stand for?",
      ["Last oral intake", "Level of consciousness", "Location of the patient's pain", "Lung sounds"],
      "SAMPLE covers signs and symptoms, allergies, medications, pertinent past history, last oral intake and events leading up. The last meal matters if surgery or vomiting is likely."),
    S(1, 2, "Reassessment", "How often should you reassess the vital signs of a stable patient while waiting for EMS?",
      ["About every 15 minutes", "Only once at the start", "Every 30 seconds", "Only when the patient asks you to check"],
      "Reassess a stable patient about every 15 minutes and an unstable patient about every 5 minutes, and after every intervention."),
    S(1, 3, "Stroke", "A woman suddenly cannot raise her right arm and her speech is slurred. Which detail is most important to find out and pass on?",
      ["The time she was last known well", "What she ate for lunch and when she ate it", "Her childhood illnesses and old surgeries", "Her insurance details and doctor's name"],
      "Stroke treatments depend on how long ago symptoms began. If no one saw the onset, the time she was last known to be normal is used. Get it and pass it on."),
    X(1, 2, "Pain assessment", "Match each OPQRST question to the letter it belongs to.",
      ["What were you doing when it started?", "What makes it better or worse?", "Does the pain go anywhere else?", "On a scale of 0 to 10, how bad is it?"],
      ["Onset", "Provocation", "Region and radiation", "Severity"], [0, 1, 2, 3],
      "Onset asks what the patient was doing when it began, provocation what changes it, region and radiation where it is and where it spreads, and severity how bad it is."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "Pupils", "After a head injury, one pupil is large and does not react to light. What should you do?",
      ["Report it as a sign of pressure on the brain", "Ignore it as a normal finding", "Keep shining a light into it until it reacts", "Cover the eye with a patch"],
      "Unequal pupils after head trauma can mean pressure building inside the skull. Report it at once to the arriving EMS crew, who will need to hurry transport."),
    S(2, 2, "Focused exam", "A responsive man complains only of pain in his right ankle after a slip. Which exam fits?",
      ["A focused exam of the ankle and leg", "A full head-to-toe exam before anything else", "No exam at all until EMS arrives on scene", "A check of his pupils and nothing else"],
      "With a minor mechanism and one complaint in an alert patient, a focused exam of the injured area, including pulse, movement and feeling below it, is enough."),
    M(2, 2, "Stroke signs", "Which findings should make you think of a stroke? Select two.",
      ["One side of the face droops", "Sudden trouble speaking", "Pain in both knees for weeks", "A cough with a fever", "A cut on the forehead"],
      "A face droop and sudden speech trouble are classic stroke signs, along with one-sided arm weakness, balance and vision changes. The other findings point elsewhere."),
    O(2, 2, "Head-to-toe exam", "Put the regions of a full-body exam of a trauma patient in order.",
      ["Head", "Neck", "Chest", "Abdomen", "Pelvis", "Legs and arms"],
      "A head-to-toe exam runs in order so nothing is missed: head, neck, chest, abdomen, pelvis, then the extremities, with the back checked when the patient is rolled."),
    # ---------- Drill only ----------
    S(0, 2, "DCAP-BTLS", "During a trauma exam, what does the T in DCAP-BTLS stand for?",
      ["Tenderness", "Temperature", "Tourniquet time", "Tremor"],
      "DCAP-BTLS stands for deformities, contusions, abrasions, punctures or penetrations, burns, tenderness, lacerations and swelling."),
    S(0, 2, "Medications", "Why ask which medicines a patient takes?",
      ["They hint at the patient's illnesses", "So you can give the patient a dose of each one", "To decide whether to wear gloves", "To check the patient's insurance before transport"],
      "A list of medicines tells you about conditions the patient may not mention, such as heart failure or diabetes. EMRs do not give the patient's own prescriptions."),
    S(0, 2, "Diabetic emergency", "A diabetic man is sweaty, shaky and confused. Under the national scope model, what can an EMR do?",
      ["Protect his airway and call for EMS", "Check his blood sugar with his own meter", "Give him oral glucose gel between cheek and gum", "Inject his own insulin"],
      "Blood glucose checks and oral glucose are EMT-level skills in the national model. An EMR keeps him safe, protects the airway, gathers the history and gets EMS on the way. State protocols may add more."),
    S(0, 2, "Reassessment", "You placed a splint on a forearm. What must you recheck after it is on?",
      ["Pulse, movement and feeling in the hand", "The patient's blood type", "Lung sounds on both sides of the chest", "The patient's pupils only"],
      "A splint can press on vessels and nerves. Check circulation, movement and sensation below the injury before and after splinting."),
    S(0, 2, "Allergies", "A patient says she is allergic to latex. What should you do?",
      ["Use latex-free gloves and report the allergy", "Use any gloves, since contact will be brief", "Skip gloves altogether", "Note it only if she reacts"],
      "Latex can trigger a serious reaction in an allergic person. Switch to non-latex equipment and pass the allergy on at handoff."),
    S(0, 2, "Events leading up", "A man is found at the bottom of a staircase. Why ask what happened before he fell?",
      ["A medical problem may have caused the fall", "It tells you who is to blame", "It replaces the need for a trauma exam", "It shows whether he needs a cervical collar"],
      "A fall may follow a faint, seizure or heart rhythm problem. Asking about events leading up helps you treat both the cause and the injury."),
    S(0, 2, "Breath sounds", "During your exam you notice a patient's breathing sounds wet and gurgling from the throat. What does this tell you?",
      ["There is fluid in the upper airway", "The lungs are clear", "The patient is asleep and resting comfortably", "The patient has a fever and a chest infection"],
      "Gurgling from the throat means fluid in the upper airway that needs suction. Snoring suggests the tongue is partly blocking the airway."),
    S(0, 2, "Altered patient history", "A patient is too confused to answer. Where can you find history?",
      ["Family, bystanders and medical ID jewelry", "Only from the patient later, once he is less confused", "From guessing his age", "From the registration papers in his car"],
      "Family, bystanders, medication bottles and medical ID jewelry can give history when the patient cannot. Note the source in your report."),
    M(0, 2, "Stroke history", "A man has sudden weakness on one side. Which facts should you gather for the EMS crew? Select two.",
      ["When he was last known well", "Who saw the symptoms start", "His favorite food", "Where he went to school", "The color of his car"],
      "Last known well and the person who saw the onset help the hospital decide on time-sensitive treatment. Bring or name the witness if you can."),
    S(0, 2, "Abdominal exam", "Where do you start when feeling a patient's belly for pain?",
      ["Away from where it hurts", "Right on the painful spot", "With deep, hard pressure over the whole belly", "Only on the left side, where the spleen is"],
      "Begin away from the painful area and move toward it last with gentle pressure, so the patient does not tense up and hide other findings."),
    S(0, 2, "Pediatric history", "A 4-year-old has a fever and a rash. Who is often the best source of her history?",
      ["Her parent or caregiver", "Her older siblings only", "A neighbor across the street", "Her school nurse's records"],
      "Caregivers know a young child's baseline, recent illness and medicines best. Talk to the child too, at her level, about what hurts."),
    S(0, 2, "Reassessment", "You reassess an unstable patient. How often should this be done?",
      ["About every 5 minutes", "About every 30 minutes", "Only once before handoff", "Only if the patient complains"],
      "Unstable patients are reassessed about every 5 minutes because their condition can change quickly; stable patients about every 15."),
]
